#[test]
fn review_disable_server_preserves_pending_accept() {
    let mut pair = Pair::default();
    pair.server.handle_incoming = Box::new(|_| IncomingConnectionBehavior::Wait);
    pair.begin_connect(client_config());
    pair.drive_client();
    pair.drive_server();
    let incoming = pair.server.waiting_incoming.pop().unwrap();
    pair.server.endpoint.set_server_config(None);
    pair.server.endpoint.accept(incoming, pair.time, &mut Vec::new(), None)
        .expect("disabling new incoming connections should preserve pending accepts");
}

#[test]
fn review_disable_server_handles_pending_retransmission() {
    let mut pair = Pair::default();
    pair.server.handle_incoming = Box::new(|_| IncomingConnectionBehavior::Wait);
    pair.begin_connect(client_config());
    pair.drive_client();
    let (when, ecn, bytes) = pair.server.inbound.front().unwrap().clone();
    pair.drive_server();
    let incoming = pair.server.waiting_incoming.pop().unwrap();
    pair.server.endpoint.set_server_config(None);
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        pair.server.endpoint.handle(when, pair.client.addr, None, ecn, bytes, &mut Vec::new())
    }));
    pair.server.endpoint.ignore(incoming);
    assert!(result.is_ok(), "pending incoming data must not panic after disabling new connections");
}

#[test]
fn review_stop_reset_stream_replenishes_stream_credit() {
    let mut transport = TransportConfig::default();
    transport.max_concurrent_uni_streams(1u32.into());
    let mut cfg = server_config();
    cfg.transport_config(Arc::new(transport));
    let mut pair = Pair::new(Default::default(), cfg);
    let (client_ch, server_ch) = pair.connect();
    let s = pair.client_streams(client_ch).open(Dir::Uni).unwrap();
    pair.client_send(client_ch, s).reset(0u32.into()).unwrap();
    pair.drive();
    pair.server_streams(server_ch).accept(Dir::Uni).unwrap();
    pair.server_recv(server_ch, s).stop(0u32.into()).unwrap();
    pair.drive();
    assert!(pair.client_streams(client_ch).open(Dir::Uni).is_some(),
        "disposing of a reset stream should release its concurrency slot");
}
